typedef long long ll;

typedef struct {
    ll val;
    int idx;
} Item;

int cmpItem(const void *a, const void *b) {
    ll x = ((const Item*)a)->val;
    ll y = ((const Item*)b)->val;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int max_int(int a, int b) {
    return a > b ? a : b;
}

/* Segment tree for range maximum */
typedef struct {
    int n;
    int *t;
} SegTree;

void seg_init(SegTree *st, int sz) {
    st->n = 1;
    while (st->n < sz) st->n <<= 1;
    st->t = (int*)calloc(2 * st->n, sizeof(int));
}

void seg_update(SegTree *st, int pos, int val) {
    pos += st->n;
    if (st->t[pos] < val) st->t[pos] = val;
    pos >>= 1;
    while (pos) {
        st->t[pos] = max_int(st->t[pos << 1], st->t[pos << 1 | 1]);
        pos >>= 1;
    }
}

int seg_query(SegTree *st, int l, int r) {
    if (l > r) return 0;
    l += st->n;
    r += st->n;
    int res = 0;
    while (l <= r) {
        if (l & 1) res = max_int(res, st->t[l++]);
        if (!(r & 1)) res = max_int(res, st->t[r--]);
        l >>= 1;
        r >>= 1;
    }
    return res;
}

int lower_bound_vals(ll *vals, int m, ll x) {
    int l = 0, r = m;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (vals[mid] < x) l = mid + 1;
        else r = mid;
    }
    return l;
}

int upper_bound_vals(ll *vals, int m, ll x) {
    int l = 0, r = m;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (vals[mid] <= x) l = mid + 1;
        else r = mid;
    }
    return l;
}

