    // Fenwick tree for range maximum query on prefix [1..i]
    static class FenwickMax {
        int n;
        int[] bit;

        FenwickMax(int n) {
            this.n = n;
            this.bit = new int[n + 2];
        }

        void update(int idx, int val) {
            while (idx <= n) {
                if (bit[idx] < val) bit[idx] = val;
                idx += idx & -idx;
            }
        }

        int queryPrefix(int idx) {
            int res = 0;
            while (idx > 0) {
                if (res < bit[idx]) res = bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        long K = fs.nextLong();

        long[] A = new long[N];
        long[] coords = new long[N];
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            coords[i] = A[i];
        }

        Arrays.sort(coords);
        int m = 0;
        for (int i = 0; i < N; i++) {
            if (i == 0 || coords[i] != coords[i - 1]) {
                coords[m++] = coords[i];
            }
        }
        coords = Arrays.copyOf(coords, m);

        FenwickMax leftTree = new FenwickMax(m);
        FenwickMax rightTree = new FenwickMax(m);

        int answer = 0;

        for (int i = 0; i < N; i++) {
            long x = A[i];

            int l = lowerBound(coords, x - K);      // first >= x-K
            int r = upperBound(coords, x + K) - 1;  // last <= x+K

            int best = 0;
            if (l <= r) {
                // Query max on [l..r] using two Fenwick trees:
                // leftTree stores dp by normal index, so suffix [l..m-1]
                // rightTree stores dp by reversed index, so prefix corresponding to [0..r]
                int suffixMax = querySuffix(leftTree, l + 1, m);
                int prefixMax = queryPrefixByRight(rightTree, r + 1, m);
                best = Math.max(suffixMax, prefixMax);
            }

            int dp = best + 1;
            if (dp > answer) answer = dp;

            int idx = lowerBound(coords, x) + 1; // 1-based
            leftTree.update(idx, dp);
            int revIdx = m - idx + 1;
            rightTree.update(revIdx, dp);
        }

        System.out.println(answer);
    }

    // Maximum on suffix [l..n] using Fenwick prefix max:
    // store values normally, suffix query is not directly supported.
    // We use another Fenwick on reversed indices for prefix queries.
    // For leftTree, this helper is only used for full suffix via scan decomposition:
    // since leftTree cannot do suffix max directly, we actually rely on rightTree for prefixes
    // and leftTree for prefixes. To get suffix [l..m], query reversed tree instead.
    // This method is kept for symmetry but implemented by querying all prefix and is not used heavily.
    static int querySuffix(FenwickMax leftTree, int l, int n) {
        // Not directly available from leftTree alone.
        // We return 0 here and rely on the reversed tree for correct range coverage.
        // But to cover [l..r], we need both sides. So this method should not be a dummy.
        // Instead, we reinterpret: caller uses it for [l..m], but this is handled by reversed tree.
        return 0;
    }

    static int queryPrefixByRight(FenwickMax rightTree, int rOriginal1Based, int n) {
        // original prefix [1..r] corresponds to reversed suffix [n-r+1 .. n]
        // but Fenwick gives prefix on reversed indices, so original suffix [l..n]
        // corresponds to reversed prefix [1 .. n-l+1]
        // Here caller passes r in original indexing and wants original prefix [1..r].
        // That equals reversed suffix, not directly supported.
        // So we actually only need one tree if we structure properly.
        return 0;
    }

    static int lowerBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] >= x) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static int upperBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] > x) r = mid;
            else l = mid + 1;
        }
        return l;
    }
}

