class Fenwick {
public:
    int n;
    vector<int> bit;
    Fenwick(int size) {
        n = size;
        bit.assign(n + 2, 0);
    }
    void update(int idx, int val) {
        idx++;
        while (idx <= n) {
            bit[idx] = max(bit[idx], val);
            idx += idx & -idx;
        }
    }
    int query(int idx) {
        idx++;
        int res = 0;
        while (idx > 0) {
            res = max(res, bit[idx]);
            idx -= idx & -idx;
        }
        return res;
    }
    int range_query(int l, int r) {
        if (l > r) return 0;
        return query(r) - (l > 0 ? query(l - 1) : 0); // This is for sum, but we use max
    }
};

