#include <bits/stdc++.h>
using namespace std;

/*
We need the longest subsequence B of A such that for every adjacent pair in B:
|B[i] - B[i-1]| <= K

DP:
dp[x] = maximum length of a valid subsequence ending with value x.

When processing a[i] = v:
new_dp = 1 + max(dp[t]) for t in [v-K, v+K]

So we need range maximum query + point update over value domain.
Since values can be large, coordinate-compress all A values only.

For each value v, among compressed coordinates we need all values in [v-K, v+K].
Use lower_bound / upper_bound on sorted unique values to get index range,
and a segment tree for range maximum.
*/

struct SegTree {
    int n;
    vector<int> st;

    SegTree(int sz = 0) { init(sz); }

    void init(int sz) {
        n = 1;
        while (n < sz) n <<= 1;
        st.assign(2 * n, 0);
    }

    void update(int pos, int val) {
        pos += n;
        st[pos] = max(st[pos], val);
        for (pos >>= 1; pos; pos >>= 1) {
            st[pos] = max(st[pos << 1], st[pos << 1 | 1]);
        }
    }

    int query(int l, int r) { // inclusive
        if (l > r) return 0;
        l += n; r += n;
        int res = 0;
        while (l <= r) {
            if (l & 1) res = max(res, st[l++]);
            if (!(r & 1)) res = max(res, st[r--]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long K;
    cin >> N >> K;

    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    vector<long long> vals = A;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    SegTree seg((int)vals.size());
    int ans = 0;

    for (long long v : A) {
        long long L = v - K;
        long long R = v + K;

        int l = lower_bound(vals.begin(), vals.end(), L) - vals.begin();
        int r = upper_bound(vals.begin(), vals.end(), R) - vals.begin() - 1;

        int best = seg.query(l, r);
        int cur = best + 1;

        int pos = lower_bound(vals.begin(), vals.end(), v) - vals.begin();
        seg.update(pos, cur);
        ans = max(ans, cur);
    }

    cout << ans << '\n';
    return 0;
}

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    # Assume input format: N K followed by N integers
    n, k = data[0], data[1]
    a = data[2:2 + n]

    # Coordinate compression of values in A
    vals = sorted(set(a))
    m = len(vals)
    idx = {v: i + 1 for i, v in enumerate(vals)}  # 1-based for segment tree

    # Iterative segment tree for range maximum query
    size = 1
    while size < m:
        size <<= 1
    seg = [0] * (2 * size)

    def range_max(l, r):
        if l > r:
            return 0
        l += size - 1
        r += size - 1
        res = 0
        while l <= r:
            if l & 1:
                if seg[l] > res:
                    res = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] > res:
                    res = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

    def update(pos, val):
        p = pos + size - 1
        if seg[p] >= val:
            return
        seg[p] = val
        p >>= 1
        while p:
            newv = seg[p << 1] if seg[p << 1] > seg[p << 1 | 1] else seg[p << 1 | 1]
            if seg[p] == newv:
                break
            seg[p] = newv
            p >>= 1

    ans = 0

    for x in a:
        left_val = x - k
        right_val = x + k

        l = lower_bound(vals, left_val) + 1
        r = upper_bound(vals, right_val)

        best = range_max(l, r) + 1
        update(idx[x], best)
        if best > ans:
            ans = best

    print(ans)

def lower_bound(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) >> 1
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def upper_bound(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) >> 1
        if arr[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo  # returns count of elements <= target, also 1-based right endpoint

